        print('DEADLOCK, remaining',remaining); break
    ready.sort(key=lambda i:(z[i],i))
    pick=ready[0]; order.append(pick); placed.add(pick); remaining.remove(pick)
print(order)
print(len(order), 'deadlock' if remaining else 'ok')

